WITH t AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin) SELECT $1,'M9-TCLOSED', min(milestone_id), 9991, 'подсадка самотеста', 'S', 'closed', 'dev', 'declared' FROM project_plan_tasks WHERE project_id=$1 RETURNING id) INSERT INTO project_task_check(project_id, task_id, check_id, said_as) SELECT $1, t.id, 'TC-PROBE-88', 'доказательство' FROM t
